class IndependentTwoSlotStrategy(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy_closes = RollingWindow[float](101)
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self.aapl_previous_close = None
        self.aapl_red_streak = 0

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0

    def OnData(self, data):
        # Market-state quantities continue updating whenever their own data exists.
        if data.Bars.ContainsKey(self.symbols["SPY"]):
            self.spy_closes.Add(float(data.Bars[self.symbols["SPY"]].Close))

        if data.Bars.ContainsKey(self.symbols["AAPL"]):
            aapl_close = float(data.Bars[self.symbols["AAPL"]].Close)
            self.aapl_rsi.Update(IndicatorDataPoint(self.Time, aapl_close))

            if self.aapl_previous_close is not None and aapl_close < self.aapl_previous_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

            self.aapl_previous_close = aapl_close
        else:
            self.aapl_previous_close = None
            self.aapl_red_streak = 0

        # Skip all rule evaluation if any subscribed ticker lacks today's bar.
        if any(not data.Bars.ContainsKey(symbol) for symbol in self.symbols.values()):
            return

        # The SPY cross requires both today's and yesterday's fully formed SMA(100).
        if self.spy_closes.Count < 101 or not self.aapl_rsi.IsReady:
            return

        spy_close = float(data.Bars[self.symbols["SPY"]].Close)
        aapl_close = float(data.Bars[self.symbols["AAPL"]].Close)

        spy_sma_today = sum(self.spy_closes[i] for i in range(100)) / 100.0
        spy_sma_yesterday = sum(self.spy_closes[i] for i in range(1, 101)) / 100.0
        spy_close_yesterday = self.spy_closes[1]

        spy_crosses_above = (
            spy_close_yesterday <= spy_sma_yesterday and
            spy_close > spy_sma_today
        )
        spy_crosses_below = (
            spy_close_yesterday >= spy_sma_yesterday and
            spy_close < spy_sma_today
        )

        # Sells are evaluated before buys.
        if self.strategy_a_lot > 0 and spy_crosses_below:
            self.MarketOrder(self.symbols["SPY"], -self.strategy_a_lot)
            self.strategy_a_lot = 0

        if self.strategy_b_lot > 0 and self.aapl_rsi.Current.Value > 60:
            self.MarketOrder(self.symbols["AAPL"], -self.strategy_b_lot)
            self.strategy_b_lot = 0

        if self.strategy_a_lot == 0 and spy_crosses_above:
            shares = int(math.floor(0.40 * self.Portfolio.TotalPortfolioValue / spy_close))
            if shares > 0:
                self.MarketOrder(self.symbols["SPY"], shares)
                self.strategy_a_lot = shares

        if self.strategy_b_lot == 0 and self.aapl_red_streak >= 3:
            if self.Portfolio.Cash >= 20_000:
                shares = int(math.floor(20_000 / aapl_close))
                if shares > 0:
                    self.MarketOrder(self.symbols["AAPL"], shares)
                    self.strategy_b_lot = shares
